ck();Need(livePlayer.Reads==1&&BloodmoonRecording.LiveNight.Kills["Player"]==0,"start and live zero");livePlayer.Kills=103;for(int j=2;j<=9;j++){liveWorld.Now++;UnityEngine.Time.unscaledTime=20+j/10f;StatisticsSync.Tick();}Need(livePlayer.Reads==1,"less than one second no resample");liveWorld.Now++;UnityEngine.Time.unscaledTime=21.2f;StatisticsSync.Tick();Need(livePlayer.Reads==2&&StatisticsSync.Snapshot().Data.Nights[0].Kills["Player"]==3,"one-second sample and live table");liveWorld.Now=7UL*24000+4000;UnityEngine.Time.unscaledTime=23;StatisticsSync.Tick();Need(BloodmoonRecording.LiveNight==null&&StatisticsSync.Snapshot().Data.Nights[0].Kills["Player"]==3,"live hidden and finished table preserved");
